import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';

describe('ToolRegistry inputSchema validation acceptance', () => {
  afterEach(() => {
    setLogger();
  });

  it('returns a ToolResponse naming the missing required property and does not invoke the executor', async () => {
    let callCount = 0;
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'get_weather',
        description: 'Look up weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        callCount += 1;
        return 'forecast';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({
      callCount,
      mentionsLocation: response.result.includes('location'),
      mentionsRequired: /required/i.test(response.result),
    }).toEqual({
      callCount: 0,
      mentionsLocation: true,
      mentionsRequired: true,
    });
  });

  it('rejects wrong-typed or disallowed-enum fields naming path and constraint without leaking values', async () => {
    const capturedLogs: Array<{category: string; message: string; fields?: Record<string, unknown>}> = [];
    const record = (category: string, message: string, fields?: Record<string, unknown>) =>
      void capturedLogs.push({category, message, fields});
    const logger: Logger = {debug: record, info: record, warn: record, error: record};
    setLogger(logger);

    let callCount = 0;
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather_check',
        description: 'Check weather with units',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'},
            units: {type: 'string', enum: ['celsius', 'fahrenheit']},
          },
          required: ['location'],
        },
      },
      async () => {
        callCount += 1;
        return 'ok';
      }
    );

    const wrongTypeResponse = await registry.execute('weather_check', {
      location: 99887766,
      secretToken: 'SECRET_PII_12345',
    });
    const wrongEnumResponse = await registry.execute('weather_check', {
      location: 'Berlin',
      units: 'SECRET_KELVIN_VAL',
    });

    const serializedLogs = JSON.stringify(capturedLogs);
    const forbiddenValues = ['99887766', 'SECRET_PII_12345', 'SECRET_KELVIN_VAL'];

    expect({
      callCount,
      typeNamesField: wrongTypeResponse.result.includes('location'),
      typeNamesExpected: /string/i.test(wrongTypeResponse.result),
      enumNamesField: wrongEnumResponse.result.includes('units'),
      enumNamesConstraint: /enum|allowed/i.test(wrongEnumResponse.result),
      leakedInTypeResult: forbiddenValues.some(secret => wrongTypeResponse.result.includes(secret)),
      leakedInEnumResult: forbiddenValues.some(secret => wrongEnumResponse.result.includes(secret)),
      leakedInLogs: forbiddenValues.some(secret => serializedLogs.includes(secret)),
    }).toEqual({
      callCount: 0,
      typeNamesField: true,
      typeNamesExpected: true,
      enumNamesField: true,
      enumNamesConstraint: true,
      leakedInTypeResult: false,
      leakedInEnumResult: false,
      leakedInLogs: false,
    });
  });

  it('throws synchronously at register time when inputSchema is uncompilable and names the tool', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_tool',
          description: 'Tool with an uncompilable schema',
          inputSchema: {type: 'unrecognized_json_type'},
        },
        async () => 'ok'
      )
    ).toThrow(/broken_tool/);
  });

  it('validates a function-valued ToolDefinitionSource against the schema current at each execute call', async () => {
    let requiredField = 'city';
    const receivedInputs: Array<Record<string, unknown>> = [];
    const registry = new ToolRegistry();
    registry.register(
      () => ({
        name: 'dynamic_lookup',
        description: 'Lookup with changing schema',
        inputSchema: {
          type: 'object',
          properties: {
            city: {type: 'string'},
            postalCode: {type: 'string'},
          },
          required: [requiredField],
        },
      }),
      async input => {
        receivedInputs.push(input);
        return 'ok';
      }
    );

    const firstResponse = await registry.execute('dynamic_lookup', {city: 'Paris'});
    requiredField = 'postalCode';
    const secondResponse = await registry.execute('dynamic_lookup', {city: 'Paris'});
    const thirdResponse = await registry.execute('dynamic_lookup', {postalCode: '75001'});

    expect({
      receivedInputs,
      firstSucceeded: firstResponse.result === 'ok',
      secondNamesPostalCode: secondResponse.result.includes('postalCode'),
      thirdSucceeded: thirdResponse.result === 'ok',
    }).toEqual({
      receivedInputs: [{city: 'Paris'}, {postalCode: '75001'}],
      firstSucceeded: true,
      secondNamesPostalCode: true,
      thirdSucceeded: true,
    });
  });
});

import {createChatOrchestrator} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, Message, MessageChunk, SendMessageParams} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

describe('ChatOrchestrator schema rejection retry acceptance', () => {
  it('resolves after a rejected tool call by returning the validation error to the model and passing the retry unchanged', async () => {
    const executorInputs: Array<Record<string, unknown>> = [];
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'get_weather',
        description: 'Look up weather for a location',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'},
            units: {type: 'string', default: 'celsius'},
          },
          required: ['location'],
        },
      },
      async input => {
        executorInputs.push(input);
        return 'Sunny, 20C';
      }
    );

    const capturedRounds: Message[][] = [];
    const rounds: MessageChunk[][] = [
      [{type: 'tool_use', toolCall: {id: 'call-1', name: 'get_weather', input: {}}}, {type: 'stop', stopReason: 'tool_use'}],
      [
        {
          type: 'tool_use',
          toolCall: {id: 'call-2', name: 'get_weather', input: {location: 'Berlin', extraTag: 'keep'}},
        },
        {type: 'stop', stopReason: 'tool_use'},
      ],
      [{type: 'text', text: 'Forecast ready.'}, {type: 'stop', stopReason: 'end_turn'}],
    ];
    let roundIndex = 0;

    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        capturedRounds.push(params.messages.map(msg => ({...msg})));
        for (const chunk of rounds[roundIndex++] ?? []) yield chunk;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };

    const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});
    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);
    const session: ChatSession = {
      sessionId: 's-retry',
      userId: 'u1',
      entries: [{role: 'user', content: 'Weather please', timestamp: SENT_AT}],
    };

    const reply = await orchestrator.processMessage(session);
    const roundOneText = extractToolResultContent(capturedRounds[1] ?? [], 'call-1');

    expect({
      reply,
      executorInputs,
      mentionsLocation: roundOneText.includes('location'),
      mentionsRequired: /required/i.test(roundOneText),
    }).toEqual({
      reply: 'Forecast ready.',
      executorInputs: [{location: 'Berlin', extraTag: 'keep'}],
      mentionsLocation: true,
      mentionsRequired: true,
    });
  });
});

function extractToolResultContent(messages: Message[], toolUseId: string): string {
  const last = messages[messages.length - 1];
  if (!last || last.role !== 'user' || typeof last.content === 'string') return '';
  const match = last.content.find(entry => entry.type === 'tool_result' && entry.toolUseId === toolUseId);
  return match?.content ?? '';
}

